                "syntaxAnalysis": "否定副词置于句首的部分倒装句。According to... 为来源状语；否定副词短语 nowhere else in colonial America 位于句首；助动词 was 提到主语 so much importance 之前；谓语动词过去分词 attached to intellectual pursuits（attach importance to 为固定搭配）。"
